// Yu–Turk broad-phase bound. One workgroup reduces the actual fitted support
// radii about ORIGINAL particle centers; no assumption of equal determinants.
// @dispatch_count_param: max_capacity
struct U { max_capacity: u32, _pad0: u32, _pad1: u32, _pad2: u32 };
struct Shape {
  surface_center_radius: vec4<f32>,
  surface_axis_x: vec4<f32>,
  surface_axis_y: vec4<f32>,
  surface_axis_z: vec4<f32>,
};
@group(0) @binding(0) var<uniform> u: U;
@group(0) @binding(1) var<storage, read> shapes: array<Shape>;
@group(0) @binding(2) var<storage, read_write> reach: array<atomic<u32>>;
var<workgroup> maxima: array<f32, 256>;
@compute @workgroup_size(256)
fn cs_main(@builtin(local_invocation_index) lane: u32) {
  var bound = 0.0;
  for (var i = lane; i < arrayLength(&shapes); i += 256u) {
    bound = max(bound, shapes[i].surface_axis_y.w);
  }
  maxima[lane] = bound;
  workgroupBarrier();
  for (var stride = 128u; stride > 0u; stride /= 2u) {
    if (lane < stride) { maxima[lane] = max(maxima[lane], maxima[lane + stride]); }
    workgroupBarrier();
  }
  if (lane == 0u) { atomicStore(&reach[0], bitcast<u32>(maxima[0])); }
}
